using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using OCRS.Data; using OCRS.Models; using OCRS.ViewModels.Account;
#pragma warning disable CS8604 // User is guarded by the null check in Login; compact action formatting confuses flow analysis.
namespace OCRS.Controllers;
public class AccountController(UserManager<ApplicationUser> users,SignInManager<ApplicationUser> signIn,ApplicationDbContext db,IWebHostEnvironment env):Controller
{
    [HttpGet] public IActionResult Register()=>View(new RegisterViewModel());
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Register(RegisterViewModel m){ if(!ModelState.IsValid)return View(m); var u=new ApplicationUser{UserName=m.Email,Email=m.Email,FullName=m.FullName,PhoneNumber=m.PhoneNumber}; var r=await users.CreateAsync(u,m.Password); if(!r.Succeeded){foreach(var e in r.Errors)ModelState.AddModelError("",e.Description);return View(m);} await users.AddToRoleAsync(u,"Student"); db.Students.Add(new Student{UserId=u.Id,StudentCode=$"HV{DateTime.UtcNow:yyMMdd}{Random.Shared.Next(1000,9999)}"}); await db.SaveChangesAsync(); TempData["Success"]="Tạo tài khoản thành công."; return RedirectToAction(nameof(Login)); }
    [HttpGet] public IActionResult Login(string? returnUrl=null)=>View(new LoginViewModel());
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Login(LoginViewModel m,string? returnUrl=null){ if(!ModelState.IsValid)return View(m); var u=await users.FindByEmailAsync(m.Email); if(u is null||!u.IsActive){ModelState.AddModelError("","Email hoặc mật khẩu không đúng.");return View(m);} var r=await signIn.PasswordSignInAsync(u,u is null?"":m.Password,m.RememberMe,true); if(!r.Succeeded){ModelState.AddModelError("",r.IsLockedOut?"Tài khoản tạm khóa do đăng nhập sai nhiều lần.":"Email hoặc mật khẩu không đúng.");return View(m);} if(Url.IsLocalUrl(returnUrl))return LocalRedirect(returnUrl); if(await users.IsInRoleAsync(u,"Admin"))return Redirect("/Admin/Dashboard"); if(await users.IsInRoleAsync(u,"Instructor"))return Redirect("/Instructor/Dashboard"); return Redirect("/MyCourses"); }
    [Authorize,HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Logout(){await signIn.SignOutAsync();return RedirectToAction("Index","Home");}
    [HttpGet] public IActionResult ForgotPassword()=>View(new ForgotPasswordViewModel());
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ForgotPassword(ForgotPasswordViewModel m){if(!ModelState.IsValid)return View(m);var u=await users.FindByEmailAsync(m.Email);if(u!=null){var token=await users.GeneratePasswordResetTokenAsync(u);if(env.IsDevelopment())TempData["DevResetLink"]=Url.Action(nameof(ResetPassword),"Account",new{email=m.Email,token},Request.Scheme);}TempData["Success"]="Nếu email tồn tại, hướng dẫn đặt lại mật khẩu đã được tạo.";return RedirectToAction(nameof(Login));}
    [HttpGet] public IActionResult ResetPassword(string email,string token)=>View(new ResetPasswordViewModel{Email=email,Token=token});
    [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ResetPassword(ResetPasswordViewModel m){if(!ModelState.IsValid)return View(m);var u=await users.FindByEmailAsync(m.Email);if(u==null)return RedirectToAction(nameof(Login));var r=await users.ResetPasswordAsync(u,m.Token,m.Password);if(r.Succeeded){TempData["Success"]="Đặt lại mật khẩu thành công.";return RedirectToAction(nameof(Login));}foreach(var e in r.Errors)ModelState.AddModelError("",e.Description);return View(m);}
}
